contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint minSum, uint deposit, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit);
        require(deposit >= minSum);
        require(am <= deposit);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: deposit}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherBefore = address(c).balance;
        c.Collect(am); if (__ESBMC_reverted()) return;
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherAfter = address(c).balance;
        assert(balAfter == balBefore - am && etherAfter == etherBefore - am);
    }
    receive() external payable {}
}

