pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 minSum, uint256 deposit, uint256 am) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        vm.assume(deposit >= minSum);
        vm.assume(am <= deposit);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: deposit}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint etherBefore = address(c).balance;
        try c.Collect(am) {} catch { return; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint etherAfter = address(c).balance;
        assertTrue(balAfter == balBefore - am && etherAfter == etherBefore - am);
    }

    function testFuzz_run(uint256 minSum, uint256 deposit, uint256 am) public {
        _run(minSum, deposit, am);
    }

    receive() external payable {}
}
